140	  /**
141	   * Get tagged record for the passed in {@link HoodieRecord}.
142	   *
143	   * @param record   instance of {@link HoodieRecord} for which tagging is requested
144	   * @param location {@link HoodieRecordLocation} for the passed in {@link HoodieRecord}
145	   * @return the tagged {@link HoodieRecord}
146	   */
147	  public static <R> HoodieRecord<R> tagAsNewRecordIfNeeded(HoodieRecord<R> record, Option<HoodieRecordLocation> location) {
148	    if (location.isPresent()) {
149	      // When you have a record in multiple files in the same partition, then <row key, record> collection
150	      // will have 2 entries with the same exact in memory copy of the HoodieRecord and the 2
151	      // separate filenames that the record is found in. This will result in setting
152	      // currentLocation 2 times and it will fail the second time. So creating a new in memory
153	      // copy of the hoodie record.
154	      HoodieRecord<R> newRecord = record.newInstance();
155	      newRecord.unseal();
156	      newRecord.setCurrentLocation(location.get());
157	      newRecord.seal();
158	      return newRecord;
159	    } else {
160	      return record;
161	    }
162	  }
