164	  /**
165	   * Tag the record to an existing location. Not creating any new instance.
166	   */
167	  public static <R> HoodieRecord<R> tagRecord(HoodieRecord<R> record, HoodieRecordLocation location) {
168	    record.unseal();
169	    record.setCurrentLocation(location);
170	    record.seal();
171	    return record;
172	  }
