186	    List<Pair<String, Long>> foundRecordKeys = new ArrayList<>();
187	    try (HoodieFileReader fileReader = HoodieIOFactory.getIOFactory(storage)
188	        .getReaderFactory(HoodieRecordType.AVRO)
189	        .getFileReader(DEFAULT_HUDI_CONFIG_FOR_READER, filePath)) {
190	      // Load all rowKeys from the file, to double-confirm
191	      if (!candidateRecordKeys.isEmpty()) {
192	        HoodieTimer timer = HoodieTimer.start();
193	        Set<Pair<String, Long>> fileRowKeys = fileReader.filterRowKeys(candidateRecordKeys.stream().collect(Collectors.toSet()));
194	        foundRecordKeys.addAll(fileRowKeys);
195	        LOG.info(String.format("Checked keys against file %s, in %d ms. #candidates (%d) #found (%d)", filePath,
196	            timer.endTimer(), candidateRecordKeys.size(), foundRecordKeys.size()));
197	        if (LOG.isDebugEnabled()) {
198	          LOG.debug("Keys matching for file " + filePath + " => " + foundRecordKeys);
199	        }
200	      }
201	    } catch (Exception e) {
202	      throw new HoodieIndexException("Error checking candidate keys against file.", e);
203	    }
204	    return foundRecordKeys;
205	  }
