150	   * Returns the {@link MetadataPartitionType} for the given partition path in the metadata table.
151	   * <p>
152	   * NOTE: For functional and secondary indexes, the partition path is prefixed with the type of the
153	   * index, e.g. {@code func_index_<indexName>} and {@code secondary_index_<indexName>}.
154	   */
155	  public static MetadataPartitionType fromPartitionPath(String partitionPath) {
156	    if (partitionPath.startsWith(HoodieTableMetadataUtil.PARTITION_NAME_FUNCTIONAL_INDEX_PREFIX)) {
157	      return FUNCTIONAL_INDEX;
158	    } else if (partitionPath.startsWith(HoodieTableMetadataUtil.PARTITION_NAME_SECONDARY_INDEX_PREFIX)) {
159	      return SECONDARY_INDEX;
160	    }
161	    for (MetadataPartitionType partitionType : values()) {
162	      if (partitionType.getPartitionPath().equals(partitionPath)) {
163	        return partitionType;
164	      }
165	    }
166	    throw new IllegalArgumentException("No MetadataPartitionType for partition path: " + partitionPath);
167	  }
